DROP TABLE IF EXISTS `evaluation_0227_to_li`;
CREATE TABLE `evaluation_0227_to_li`  (
  `id` bigint(20) NOT NULL COMMENT '定检id',
  `regular_unit_id` bigint(20) NULL DEFAULT NULL COMMENT '定检单元id',
  `highway_segment_id` bigint(20) NULL DEFAULT NULL COMMENT '路段id',
  `highway_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '路线类型（字典：1 主线；2 匝道；3 其他）',
  `interchange_id` bigint(20) NULL DEFAULT NULL COMMENT '互通id',
  `ramp_id` bigint(20) NULL DEFAULT NULL COMMENT '匝道id',
  `highway_code` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '路线编码',
  `highway_segment_simple_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '路段简称',
  `check_year` date NULL DEFAULT NULL COMMENT '检测时间',
  `evaluation_unit` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '评价单元(字典：1 千米；2 百米)',
  `direction` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '行车方向（字典：11 上行；12 下行； 20双向）',
  `roadway` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '车道（字典：1 1车道；2 2车道；3 3车道；4 4车道；5 5车道）',
  `start_pile_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '起点桩号名称',
  `start_pile_code` decimal(20, 3) NULL DEFAULT NULL COMMENT '起点桩号编号',
  `start_pile_unit` varchar(4) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '起点桩号单位',
  `end_pile_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '终点桩号名称',
  `end_pile_code` decimal(20, 3) NULL DEFAULT NULL COMMENT '终点桩号编号',
  `end_pile_unit` varchar(4) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '终点桩号单位',
  `center_pile_code` decimal(20, 3) NULL DEFAULT NULL COMMENT '中心桩号编号',
  `check_length` int(20) NULL DEFAULT NULL COMMENT '单元长度',
