  `rdi` decimal(20, 2) NULL DEFAULT NULL COMMENT 'RDI',
  `bilateral_rqi` decimal(20, 2) NULL DEFAULT NULL COMMENT '双侧RQI',
  `rqi` decimal(20, 2) NULL DEFAULT NULL COMMENT '右侧RQI',
  `pbi` decimal(20, 2) NULL DEFAULT NULL COMMENT 'PBI',
  `pwi` decimal(20, 2) NULL DEFAULT NULL COMMENT 'PWI',
  `pqi_gp` varchar(4) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'PQI国标评定',
  `pci_gp` varchar(4) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'PCI国标评定',
  `rdi_gp` varchar(4) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'RDI国标评定',
  `rqi_gp` varchar(4) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'RQI国标评定',
  `pbi_gp` varchar(4) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'PBI国标评定',
  `pwi_gp` varchar(4) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'PWI国标评定',
  `sri_gp` varchar(4) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'SRI国标评定',
  `pssi_gp` varchar(4) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'PSSI国标评定',
  `all_right_rqi_standard` varchar(4) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '全指标(右侧RQI达标)',
  `whole_bilateral_sp` varchar(4) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '全指标（双侧RQI）省标评定',
  `bilateral_rqi_gp` varchar(4) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'RQI国标评定',
  `sri` decimal(20, 2) NULL DEFAULT NULL COMMENT 'SRI',
  `pssi` decimal(20, 2) NULL DEFAULT NULL COMMENT 'PSSI',
  `dr` decimal(20, 2) NULL DEFAULT NULL COMMENT 'DR(%)',
  `rd` decimal(20, 2) NULL DEFAULT NULL COMMENT 'RD(mm)',
  `rd_collect_degree` decimal(20, 2) NULL DEFAULT NULL COMMENT 'RD集度',
  `bilateral_iri` decimal(20, 2) NULL DEFAULT NULL COMMENT '双侧IRI',
  `iri` decimal(20, 2) NULL DEFAULT NULL COMMENT '右侧IRI(m/km)',
  `iri_collect_degree` decimal(20, 2) NULL DEFAULT NULL COMMENT 'IRI集度',
  `mpdl` decimal(20, 2) NULL DEFAULT NULL COMMENT 'MPDL(mm)',
  `mpdc` decimal(20, 2) NULL DEFAULT NULL COMMENT 'MPDC(mm)',
  `mpdr` decimal(20, 2) NULL DEFAULT NULL COMMENT 'MPDR(mm)',
  `mpd_behalf` decimal(20, 2) NULL DEFAULT NULL COMMENT 'MPD代表值(mm)',
  `pbl` int(10) NULL DEFAULT NULL COMMENT 'PBL(个)',
  `pbm` int(10) NULL DEFAULT NULL COMMENT 'PBM(个)',
  `pbh` int(10) NULL DEFAULT NULL COMMENT 'PBH(个)',
  `bilateral_pqi_gp` varchar(4) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '双侧轮PQI国标评定',
  `pci_sp` varchar(4) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'PCI省厅评定',
  `rdi_sp` varchar(4) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT 'RDI省厅评定',
  `bilateral_rqi_sp` varchar(4) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '双侧RQI省标评定',
  `bilateral_pqi_sp` varchar(4) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '双侧PQI省标评定',
  `rqi_sp` varchar(4) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT 'RQI省厅评定',
  `pqi_sp` varchar(4) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'PQI省厅评定',
  `pwi_sp` varchar(4) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'PWI省厅评定',
  `pbi_sp` varchar(4) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'PBI省厅评定',
