  `legal_unit_id` bigint(20) NULL DEFAULT NULL COMMENT '法人主体单位id',
  `legal_unit_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '法人主体单位名称',
  `data_source` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '数据来源（1 集团检；2 省检）',
  `wr` decimal(10, 2) NULL DEFAULT NULL COMMENT 'WR(%)',
  `disease_repair_rate` decimal(10, 2) NULL DEFAULT NULL COMMENT '病害修补率',
  `crack_repair_rate` decimal(10, 2) NULL DEFAULT NULL COMMENT '裂缝修补率',
  `crack` decimal(10, 2) NULL DEFAULT NULL COMMENT '龟裂(㎡)',
  `massive_crack` decimal(10, 2) NULL DEFAULT NULL COMMENT '块状裂缝(㎡)',
  `longitudinal_crack` decimal(10, 2) NULL DEFAULT NULL COMMENT '纵裂(㎡)',
  `cross_crack` decimal(10, 2) NULL DEFAULT NULL COMMENT '横裂(㎡)',
  `pit_slot` decimal(10, 2) NULL DEFAULT NULL COMMENT '坑槽(㎡)',
  `loose` decimal(10, 2) NULL DEFAULT NULL COMMENT '松散(㎡)',
  `sink` decimal(10, 2) NULL DEFAULT NULL COMMENT '沉陷(㎡)',
  `rut` decimal(10, 2) NULL DEFAULT NULL COMMENT '车辙(㎡)',
  `wave_bulge` decimal(10, 2) NULL DEFAULT NULL COMMENT '波浪拥包(㎡)',
  `flood_oil` decimal(10, 2) NULL DEFAULT NULL COMMENT '泛油(㎡)',
  `pumping` decimal(10, 2) NULL DEFAULT NULL COMMENT '唧浆(㎡)',
  `massive_repair` decimal(10, 2) NULL DEFAULT NULL COMMENT '块状修补(㎡)',
  `across_repair` decimal(10, 2) NULL DEFAULT NULL COMMENT '横向修补(㎡)',
  `portrait_repair` decimal(10, 2) NULL DEFAULT NULL COMMENT '纵向修补(㎡)',
  `crack_area_subtotal` decimal(10, 2) NULL DEFAULT NULL COMMENT '裂缝类面积小计(㎡)',
  `repair_area_subtotal` decimal(12, 2) NULL DEFAULT NULL COMMENT '修补类面积小计(㎡)',
  `area_total` decimal(12, 2) NULL DEFAULT NULL COMMENT '病害面积总计(㎡)',
  `create_user` bigint(20) NULL DEFAULT NULL COMMENT '创建人',
  `create_dept` bigint(20) NULL DEFAULT NULL COMMENT '创建部门',
  `create_time` datetime(0) NULL DEFAULT NULL COMMENT '创建时间',
  `update_user` bigint(20) NULL DEFAULT NULL COMMENT '修改人',
  `update_time` datetime(0) NULL DEFAULT NULL COMMENT '修改时间',
  `status` int(2) NULL DEFAULT NULL COMMENT '状态',
  `is_deleted` int(2) NULL DEFAULT 0 COMMENT '是否已删除',
  `crack_area_repair` decimal(10, 2) NULL DEFAULT NULL COMMENT '裂缝修补(㎡)',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `road_idx`(`highway_code`, `highway_segment_simple_name`, `management_unit_id`, `check_year`) USING BTREE,
  INDEX `year_idx`(`check_year`, `data_source`) USING BTREE,
  INDEX `data_source`(`check_year`, `data_source`, `evaluation_unit`, `highway_segment_id`, `management_unit_id`) USING BTREE,
  INDEX `highway_segment_idx`(`highway_segment_id`, `check_year`) USING BTREE,
  INDEX `regular_unit_id`(`regular_unit_id`) USING BTREE,
  INDEX `highway_segment_id`(`highway_segment_id`, `direction`, `roadway`, `end_pile_code`, `start_pile_code`) USING BTREE,
  INDEX `evaluation_unit`(`evaluation_unit`, `data_source`, `is_deleted`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '定检数据' ROW_FORMAT = Dynamic;

